const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define north-central Chile region (Coquimbo area)
  const region = ee.Geometry.Rectangle([-71.5, -31.5, -69.5, -29.5]);

  // Cloud masking function for Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDSI and count snow pixels
  function calculateSnow(image) {
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    const snow = ndsi.gt(0.4);
    return snow;
  }

  // Get images for July 7, 2022
  const col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2022-07-07', '2022-07-08')
    .map(maskClouds);

  const size1 = await col1.size().getInfo();

  // Get images for July 16, 2022
  const col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2022-07-16', '2022-07-17')
    .map(maskClouds);

  const size2 = await col2.size().getInfo();

  console.log(`July 7 images: ${size1}`);
  console.log(`July 16 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('Missing data for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // Process July 7 data
  const img1 = col1.median();
  const snow1 = calculateSnow(img1);

  const stats1 = await snow1.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const snowCount1 = stats1.NDSI_sum || 0;
  const pixelCount1 = stats1.NDSI_count || 0;

  // Process July 16 data
  const img2 = col2.median();
  const snow2 = calculateSnow(img2);

  const stats2 = await snow2.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const snowCount2 = stats2.NDSI_sum || 0;
  const pixelCount2 = stats2.NDSI_count || 0;

  console.log(`July 7: Snow pixels=${snowCount1}, Valid pixels=${pixelCount1}`);
  console.log(`July 16: Snow pixels=${snowCount2}, Valid pixels=${pixelCount2}`);

  if (pixelCount1 === 0 || pixelCount2 === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (snowCount1 === null || snowCount2 === null || 
      isNaN(snowCount1) || isNaN(snowCount2)) {
    console.log('Invalid calculation results');
    console.log('<answer>C3</answer>');
    return;
  }

  if (snowCount2 > snowCount1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
